/* The wildflower patch. GENERATED by build/build_flowers.py — edit this template, not js/effects/flowers.js. `data-static` switches the growing off, which is what draw.html does. Load userflowers.js first. */

(function () {
  'use strict';

  // How near the pointer a flower has to be to open, as a fraction of the patch.
  const BLOOM_RADIUS = 0.075;

  const MARKUP = `__MARKUP__`;

  const host = document.querySelector('.flowers');
  if (!host) return;
  host.innerHTML = MARKUP;

  const svg = host.querySelector('svg');
  // The artwork's own size would fix it on screen; the page's .flowers box decides instead.
  svg.removeAttribute('width');
  svg.removeAttribute('height');

  if (window.UserFlowers) window.UserFlowers.applyTo(svg);

  // Each centre as a fraction of the patch, measured once so the test below is arithmetic.
  function collect() {
    return Array.from(svg.querySelectorAll('.flower')).map((flower) => {
      const box = flower.querySelector('.head').getBBox();
      return {
        el: flower,
        fx: (box.x + box.width / 2) / 447,
        fy: (box.y + box.height / 2) / 114,
        open: false,
        wave: false,
      };
    });
  }

  let spots = collect();

  /* A wave breaking off the left edge. The front is an arc spreading from one
     point on that edge, and every flower is nudged off it, so it washes over
     the patch instead of crossing in step. The sun holds them up; they go down
     the same way. */
  const WAVE_SPAN = 400;      // ms for the front to reach the far edge
  const WAVE_ARC = 0.5;       // how much of the patch's height counts as distance
  const WAVE_SCATTER = 150;   // ms a flower may lead or trail the front

  const Flowers = (window.Flowers = window.Flowers || {});
  let waveTimers = [];

  function sweep(step) {
    waveTimers.forEach(clearTimeout);
    waveTimers = [];
    const from = Math.random();   // where along the left edge it breaks

    for (const spot of spots) {
      const dy = (spot.fy - from) * WAVE_ARC;
      const at = Math.hypot(spot.fx + 0.04, dy) * WAVE_SPAN +
                 Math.random() * WAVE_SCATTER;
      waveTimers.push(setTimeout(step, at, spot));
    }
  }

  function up(spot) {
    spot.wave = true;
    spot.el.classList.add('bloom');
  }

  function down(spot) {
    spot.wave = false;
    spot.el.classList.remove('shake');
    // The pointer may be holding this one open on its own.
    if (!spot.open) spot.el.classList.remove('bloom');
  }

  Flowers.raise = function () { sweep(up); };
  Flowers.lower = function () { sweep(down); };

  // A small nudge on whatever is standing, head and stem together. Cleared on a
  // timer rather than animationend, which never comes if the animation is off.
  const SHAKE_MS = 560;
  let shakeTimer = 0;

  function unshake() {
    for (const spot of spots) spot.el.classList.remove('shake');
  }

  Flowers.shake = function () {
    unshake();
    svg.getBoundingClientRect();   // let the removal land before it is set again
    for (const spot of spots) {
      if (spot.el.classList.contains('bloom')) spot.el.classList.add('shake');
    }
    clearTimeout(shakeTimer);
    shakeTimer = setTimeout(unshake, SHAKE_MS);
  };

  if (host.hasAttribute('data-static')) return;

  let pointerX = -9999;
  let pointerY = -9999;
  let pending = false;

  document.addEventListener('mousemove', (e) => {
    pointerX = e.clientX;
    pointerY = e.clientY;
    schedule();
  });

  document.addEventListener('mouseleave', () => {
    pointerX = pointerY = -9999;
    schedule();
  });

  window.addEventListener('resize', schedule);
  document.addEventListener('beetalk', schedule);

  // At most one pass per frame however many events arrive.
  function schedule() {
    if (pending) return;
    pending = true;
    requestAnimationFrame(update);
  }

  function update() {
    pending = false;

    // The bee's bubble covers the patch and the pointer is not the bee's any more.
    if (document.documentElement.classList.contains('bee-talking')) {
      closeAll();
      return;
    }

    const rect = svg.getBoundingClientRect();
    if (!rect.width) return;

    const radius = rect.width * BLOOM_RADIUS;

    for (const spot of spots) {
      const dx = rect.left + spot.fx * rect.width - pointerX;
      const dy = rect.top + spot.fy * rect.height - pointerY;
      const open = Math.hypot(dx, dy) < radius;
      if (open !== spot.open) {
        spot.open = open;
        if (open) spot.el.classList.add('bloom');
        else if (!spot.wave) spot.el.classList.remove('bloom');
      }
    }
  }

  function closeAll() {
    for (const spot of spots) {
      if (!spot.open) continue;
      spot.open = false;
      if (!spot.wave) spot.el.classList.remove('bloom');
    }
  }
})();
